-- Detailed Mistral Small 4 / Medium 3.5 enrichment. Sources verified 2026-09-07.
INSERT INTO models (slug,name,developer,release_date,ga_date,access,family,comparison_data,sources,notes,metadata,verified_at)
SELECT s.slug,s.name,s.developer,s.release_date::date,NULLIF(s.ga_date,'')::date,s.access,s.family,s.comparison_data,s.sources,s.notes,s.metadata,NOW()
FROM jsonb_to_recordset($models$
[{"slug":"mistral-small-4","name":"Mistral Small 4","developer":"Mistral AI","release_date":"2026-03-16","ga_date":"2026-03-16","access":"open_source","family":"Mistral Small 4","comparison_data":{"Developer":"Mistral AI","Release date":"2026-03-16","API model ID":"mistral-small-2603","Context window":"256K tokens","Reasoning / effort":"Configurable reasoning effort","Input / 1M tokens":"$0.15","Cached input / 1M":"$0.015","Output / 1M tokens":"$0.60","Text input":"Yes","Image / vision input":"Yes","Audio input":"No native audio input documented","Video input":"No native video input documented","Text output":"Yes","Image output":"No","Audio output":"No","Video output":"No","Tool / function calling":"Yes; function calling, built-in tools, agents and structured outputs","Computer use":"Via agent integrations; no native computer-use API documented","API access":"Yes","Product access":"Mistral API + downloadable weights","Weights / license":"Open source — Apache 2.0"},"sources":[{"title":"Introducing Mistral Small 4","url":"https://mistral.ai/news/mistral-small-4/"},{"title":"Mistral Small 4 docs","url":"https://docs.mistral.ai/models/mistral-small-4-0-26-03"},{"title":"Mistral API pricing","url":"https://docs.mistral.ai/inference/pricing"}],"notes":"119B-total / 6.5B-active hybrid model unifying instruct, reasoning, multimodal and agentic-coding capabilities.","metadata":{"verification_pass":"qwen-mistral-zai-2026-09-07","parameters_total":"119B","parameters_active":"6.5B","license":"Apache 2.0"}},{"slug":"mistral-medium-3-5","name":"Mistral Medium 3.5","developer":"Mistral AI","release_date":"2026-04-28","ga_date":"2026-04-28","access":"open_weights","family":"Mistral Medium 3.5","comparison_data":{"Developer":"Mistral AI","Release date":"2026-04-28","API model ID":"mistral-medium-3-5","Context window":"256K tokens","Reasoning / effort":"Configurable reasoning effort","Input / 1M tokens":"$1.50","Cached input / 1M":"$0.15","Output / 1M tokens":"$7.50","Text input":"Yes","Image / vision input":"Yes","Audio input":"No native audio input documented","Video input":"No native video input documented","Text output":"Yes","Image output":"No","Audio output":"No","Video output":"No","Tool / function calling":"Yes; function calling, agents, structured outputs and batching","Computer use":"Via long-horizon agent integrations","API access":"Yes","Product access":"Le Chat + Vibe + Mistral API + weights","Weights / license":"Open weights — Modified MIT"},"sources":[{"title":"Mistral Medium 3.5 docs","url":"https://docs.mistral.ai/models/mistral-medium-3-5-26-04"},{"title":"Remote agents in Vibe powered by Mistral Medium 3.5","url":"https://mistral.ai/news/vibe-remote-agents-mistral-medium-3-5/"},{"title":"Mistral API pricing","url":"https://docs.mistral.ai/inference/pricing"}],"notes":"Dense 128B multimodal model optimized for long-horizon coding and agent work. Current docs mark the v26.04 release GA under a Modified MIT license.","metadata":{"verification_pass":"qwen-mistral-zai-2026-09-07","parameters_total":"128B","parameters_active":"128B","license":"Modified MIT"}}]
$models$::jsonb) AS s(slug text,name text,developer text,release_date text,ga_date text,access text,family text,comparison_data jsonb,sources jsonb,notes text,metadata jsonb)
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,developer=EXCLUDED.developer,release_date=EXCLUDED.release_date,ga_date=EXCLUDED.ga_date,access=EXCLUDED.access,family=EXCLUDED.family,comparison_data=COALESCE(models.comparison_data,'{}'::jsonb)||EXCLUDED.comparison_data,sources=EXCLUDED.sources,notes=EXCLUDED.notes,metadata=COALESCE(models.metadata,'{}'::jsonb)||EXCLUDED.metadata,verified_at=NOW(),updated_at=NOW();

INSERT INTO model_benchmarks (id,model_slug,category,benchmark_name,benchmark_version,score_numeric,score_display,score_unit,tools,reasoning_effort,harness,evaluator,evaluation_date,source,notes,updated_at)
SELECT b.id,b.model_slug,b.category,b.benchmark_name,b.benchmark_version,b.score_numeric,b.score_display,b.score_unit,b.tools,b.reasoning_effort,b.harness,b.evaluator,NULLIF(b.evaluation_date,'')::date,b.source,b.notes,NOW()
FROM jsonb_to_recordset($benchmarks$
[{"id":"tq-20260907-030-mistral-small-4-aalcr","model_slug":"mistral-small-4","category":"other","benchmark_name":"AA-LCR","benchmark_version":null,"score_numeric":0.72,"score_display":"0.72","score_unit":"score","tools":null,"reasoning_effort":"reasoning","harness":null,"evaluator":"Mistral AI","evaluation_date":"2026-03-16","source":"https://mistral.ai/news/mistral-small-4/","notes":"First-party score; non-canonical comparison row retained as normalized evidence."},{"id":"tq-20260907-030-mistral-medium-3-5-swev","model_slug":"mistral-medium-3-5","category":"coding","benchmark_name":"SWE-bench Verified","benchmark_version":null,"score_numeric":77.6,"score_display":"77.6%","score_unit":"percent","tools":null,"reasoning_effort":null,"harness":null,"evaluator":"Mistral AI","evaluation_date":"2026-04-28","source":"https://mistral.ai/news/vibe-remote-agents-mistral-medium-3-5/","notes":null},{"id":"tq-20260907-030-mistral-medium-3-5-tau3","model_slug":"mistral-medium-3-5","category":"agentic_computer_use","benchmark_name":"τ³-Telecom","benchmark_version":null,"score_numeric":91.4,"score_display":"91.4%","score_unit":"percent","tools":null,"reasoning_effort":null,"harness":null,"evaluator":"Mistral AI","evaluation_date":"2026-04-28","source":"https://mistral.ai/news/vibe-remote-agents-mistral-medium-3-5/","notes":"First-party agentic score; benchmark is retained normalized even though it is not in the comparison template."}]
$benchmarks$::jsonb) AS b(id text,model_slug text,category text,benchmark_name text,benchmark_version text,score_numeric double precision,score_display text,score_unit text,tools boolean,reasoning_effort text,harness text,evaluator text,evaluation_date text,source text,notes text)
ON CONFLICT (id) DO UPDATE SET model_slug=EXCLUDED.model_slug,category=EXCLUDED.category,benchmark_name=EXCLUDED.benchmark_name,benchmark_version=EXCLUDED.benchmark_version,score_numeric=EXCLUDED.score_numeric,score_display=EXCLUDED.score_display,score_unit=EXCLUDED.score_unit,tools=EXCLUDED.tools,reasoning_effort=EXCLUDED.reasoning_effort,harness=EXCLUDED.harness,evaluator=EXCLUDED.evaluator,evaluation_date=EXCLUDED.evaluation_date,source=EXCLUDED.source,notes=EXCLUDED.notes,updated_at=NOW();

WITH r AS (
 SELECT b.model_slug,b.benchmark_name,b.evaluation_date,b.id,b.score_display||CASE WHEN concat_ws('; ',CASE WHEN b.benchmark_version IS NOT NULL AND lower(trim(b.benchmark_version))<>'public' AND position(lower(b.benchmark_version) in lower(b.benchmark_name))=0 THEN b.benchmark_version END,CASE WHEN b.tools IS TRUE THEN 'tools' WHEN b.tools IS FALSE THEN 'no tools' END,b.reasoning_effort)<>'' THEN ' ('||concat_ws('; ',CASE WHEN b.benchmark_version IS NOT NULL AND lower(trim(b.benchmark_version))<>'public' AND position(lower(b.benchmark_version) in lower(b.benchmark_name))=0 THEN b.benchmark_version END,CASE WHEN b.tools IS TRUE THEN 'tools' WHEN b.tools IS FALSE THEN 'no tools' END,b.reasoning_effort)||')' ELSE '' END rendered
 FROM model_benchmarks b WHERE b.model_slug IN ('mistral-small-4','mistral-medium-3-5')
),g AS (SELECT model_slug,benchmark_name,string_agg(rendered,' · ' ORDER BY evaluation_date NULLS LAST,id) rendered FROM r GROUP BY model_slug,benchmark_name),x AS (
 SELECT c.id,jsonb_agg(CASE WHEN jsonb_typeof(be.block->'rows')='array' THEN jsonb_set(be.block,'{rows}',COALESCE((SELECT jsonb_agg(CASE WHEN jsonb_typeof(re.row_value)='array' AND jsonb_array_length(re.row_value)>=3 THEN jsonb_set(jsonb_set(re.row_value,'{1}',to_jsonb(CASE WHEN COALESCE(re.row_value->>1,'')='' AND a.rendered IS NOT NULL THEN a.rendered ELSE COALESCE(re.row_value->>1,'') END),false),'{2}',to_jsonb(CASE WHEN COALESCE(re.row_value->>2,'')='' AND d.rendered IS NOT NULL THEN d.rendered ELSE COALESCE(re.row_value->>2,'') END),false) ELSE re.row_value END ORDER BY re.ord) FROM jsonb_array_elements(be.block->'rows') WITH ORDINALITY re(row_value,ord) LEFT JOIN g a ON a.model_slug=c.metadata->>'modelA' AND lower(a.benchmark_name)=lower(COALESCE(re.row_value->>0,'')) LEFT JOIN g d ON d.model_slug=c.metadata->>'modelB' AND lower(d.benchmark_name)=lower(COALESCE(re.row_value->>0,''))),'[]'::jsonb),true) ELSE be.block END ORDER BY be.ord) blocks
 FROM content_items c CROSS JOIN LATERAL jsonb_array_elements(COALESCE(c.blocks,'[]'::jsonb)) WITH ORDINALITY be(block,ord)
 WHERE c.kind='comparison' AND (c.metadata->>'modelA' IN ('mistral-small-4','mistral-medium-3-5') OR c.metadata->>'modelB' IN ('mistral-small-4','mistral-medium-3-5')) GROUP BY c.id,c.metadata)
UPDATE content_items c SET blocks=x.blocks,updated_at=NOW() FROM x WHERE c.id=x.id AND c.blocks IS DISTINCT FROM x.blocks;